export const ASKING_FOR_HELP_ACTIVITIES = [
{n:1,type:"mcq",micro:"Semua orang butuh bantuan",q:"Manakah pernyataan yang tepat tentang meminta bantuan?",options:["setiap orang membutuhkan bantuan orang lain pada suatu saat","hanya anak kecil yang boleh meminta bantuan, sedangkan yang sudah besar harus mandiri","orang yang kuat tidak pernah membutuhkan siapa pun dalam kehidupannya sehari-hari"],answer:0,explain:"Membutuhkan bantuan adalah bagian normal dari menjadi manusia, di segala usia.",hint:"Semua orang, kadang-kadang."},
{n:2,type:"mcq",micro:"Meminta bantuan itu kekuatan",q:"Meminta bantuan saat kesulitan lebih tepat disebut...",options:["hal yang harus dihindari sebisa mungkin","tanda keberanian & kebijaksanaan","tanda kelemahan yang memalukan"],answer:1,explain:"Mengenali batas & mencari bantuan menunjukkan kesadaran diri & keberanian.",hint:"Berani, bukan lemah."},
{n:3,type:"mcq",micro:"Jenis bantuan",q:"Contoh bantuan emosional adalah...",options:["seseorang meminjamkan penggaris kepadamu saat kamu lupa membawa alat tulis ke sekolah","seseorang menjelaskan cara mengerjakan soal matematika yang sulit kepadamu di kelas","seseorang mendengarkan saat kamu sedih & menemanimu"],answer:2,explain:"Bantuan bisa berupa akademik, praktis, emosional, atau soal keselamatan.",hint:"Yang mana soal perasaan?"},
{n:4,type:"mcq",micro:"Siapa orang dewasa tepercaya",q:"Orang dewasa tepercaya adalah orang yang...",options:["mendengarkan, menjagamu tetap aman, & menanggapi seriusan masalahmu","selalu setuju dengan semua yang kamu inginkan dan tidak pernah melarang apa pun yang kamu lakukan","berjanji merahasiakan apa pun yang kamu ceritakan tanpa kecuali, bahkan bila kamu dalam bahaya"],answer:0,explain:"Orang dewasa tepercaya bisa orang tua, guru, konselor, kerabat, atau pelatih yang peduli & bertanggung jawab.",hint:"Mendengar + menjaga aman."},
{n:5,type:"mcq",micro:"Masalah sendiri vs perlu orang dewasa",q:"Manakah masalah yang sebaiknya melibatkan orang dewasa tepercaya?",options:["kamu kalah dalam permainan papan saat bermain bersama teman-temanmu pada waktu istirahat","kamu atau temanmu merasa tidak aman atau memikirkan menyakiti diri","kamu bingung memilih warna sampul buku catatan baru yang akan kamu pakai semester ini"],answer:1,explain:"Hal yang menyangkut keselamatan atau perasaan yang sangat berat selalu perlu bantuan orang dewasa.",hint:"Keselamatan = orang dewasa."},
{n:6,type:"tf",micro:"Teman yang baik memberi tahu orang dewasa",q:"Benar atau Salah: Menjadi teman yang baik kadang berarti memberi tahu orang dewasa tepercaya ketika temanmu dalam bahaya, meski ia memintamu merahasiakannya.",answer:true,explain:"Keselamatan lebih penting daripada janji rahasia; memberi tahu orang dewasa adalah bentuk kepedulian sejati.",hint:"Keselamatan di atas rahasia."},
{n:7,type:"mcq",micro:"Batas sebagai penolong",q:"Saat temanmu sedang kesulitan berat, kamu...",options:["harus menyelesaikan semua masalahnya sendirian karena kamu satu-satunya orang yang ia percaya","sebaiknya menjauh darinya supaya kamu tidak ikut repot dan terbebani oleh masalah-masalahnya","bisa mendukung, tapi tidak bisa & tidak seharusnya menjadi satu-satunya penolongnya"],answer:2,explain:"Kamu bisa peduli sambil mengajak orang dewasa; beban berat butuh lebih dari satu orang.",hint:"Dukung + libatkan orang dewasa."},
{n:8,type:"mcq",micro:"Mendengarkan vs memperbaiki",q:"Sering kali, hal pertama yang dibutuhkan teman yang sedih adalah...",options:["didengarkan tanpa dihakimi, bukan langsung diberi banyak nasihat","daftar solusi yang panjang dan terperinci tentang apa saja yang harus segera ia lakukan","diberi tahu bahwa masalahnya sepele dan tidak perlu dipikirkan sampai sesedih itu"],answer:0,explain:"Mendengarkan dengan hadir penuh sering lebih menolong daripada buru-buru memberi saran.",hint:"Dengar dulu."},
{n:9,type:"mcq",micro:"Rahasia yang tak bisa disimpan",q:"Beberapa hal tidak bisa dijanjikan untuk dirahasiakan, yaitu ketika...",options:["seseorang bercerita tentang film favoritnya yang baru saja ia tonton bersama keluarganya","ada seseorang yang mungkin terluka atau dalam bahaya","seseorang menceritakan hobi barunya yang membuatnya bersemangat setiap akhir pekan"],answer:1,explain:"Bila keselamatan terancam, orang dewasa perlu tahu; ini bukan pengkhianatan.",hint:"Bahaya = perlu diberitahukan."},
{n:10,type:"mcq",micro:"Meminta bantuan lebih awal",q:"Meminta bantuan lebih awal, sebelum masalah menumpuk, biasanya...",options:["membuat orang lain marah","selalu terlalu cepat & tidak perlu","membuat masalah lebih mudah ditangani"],answer:2,explain:"Semakin awal dibantu, biasanya semakin ringan jalan keluarnya.",hint:"Lebih awal = lebih ringan."},
{n:11,type:"tf",micro:"Malu bukan alasan cukup",q:"Benar atau Salah: Rasa malu adalah alasan yang cukup kuat untuk tidak pernah meminta bantuan, meski masalahmu makin berat.",answer:false,explain:"Sebaliknya, rasa malu itu wajar tapi bukan alasan untuk menanggung sendiri; orang yang tepat tidak akan menghakimimu.",hint:"Malu itu wajar, bukan penghalang mutlak."},
{n:12,type:"mcq",micro:"Bantuan akademik",q:"Cara meminta bantuan belajar yang jelas kepada guru:",options:["'Bu, saya bingung di bagian pecahan campuran. Boleh dijelaskan ulang?'","'Bu, saya tidak mengerti apa-apa dalam pelajaran ini, semuanya terasa sangat sulit sekali'","diam saja di tempat duduk dan berharap guru menyadari sendiri bahwa kamu sedang kesulitan"],answer:0,explain:"Menyebut bagian yang sulit secara spesifik memudahkan guru membantu.",hint:"Sebut bagian yang spesifik."},
{n:13,type:"tf",micro:"Takut merepotkan",q:"Benar atau Salah: Kamu sebaiknya tidak pernah meminta bantuan orang dewasa karena mereka pasti merasa direpotkan.",answer:false,explain:"Sebaliknya, orang dewasa tepercaya yang peduli umumnya senang dimintai bantuan oleh anak atau remaja, bukan merasa direpotkan.",hint:"Mereka ingin membantu."},
{n:14,type:"mcq",micro:"Tanda peringatan pada teman",q:"Manakah tanda yang perlu kamu perhatikan pada teman & ceritakan ke orang dewasa?",options:["ia sesekali lupa membawa buku pelajaran ke sekolah lalu meminjam kepada teman sebangkunya","ia menarik diri, sering menangis, atau berbicara tentang 'tidak ada gunanya hidup'","ia sedang bersemangat dan senang sekali karena baru saja memenangkan sebuah lomba di sekolah"],answer:1,explain:"Perubahan besar, menarik diri, atau bicara tentang keputusasaan adalah tanda serius yang perlu bantuan orang dewasa.",hint:"Menarik diri & bicara putus asa."},
{n:15,type:"open",micro:"Orang tepercayamu",q:"Sebutkan dua orang dewasa yang bisa kamu mintai bantuan, & satu hal yang membuatmu percaya pada mereka.",explain:"Mengetahui lebih dulu siapa yang bisa dihubungi membuat lebih mudah meminta bantuan saat dibutuhkan.",hint:"Dua nama + alasan kamu percaya.",sample:"Aku bisa meminta bantuan ke ibuku & wali kelasku, Bu Sari. Aku percaya pada mereka karena mereka mau mendengar tanpa langsung marah, & dulu saat aku cerita soal masalah dengan teman, mereka membantuku tanpa membuatku merasa bodoh."},
{n:16,type:"mcq",micro:"Bukan tugasmu sendirian",q:"Jika temanmu bercerita tentang masalah keluarga yang berat, hal terbaik yang bisa kamu lakukan:",options:["berjanji akan menyelesaikan semua masalah keluarganya sendirian tanpa memberi tahu siapa pun","menyuruhnya berhenti mengeluh dan lebih bersyukur karena masih banyak yang nasibnya lebih buruk","dengarkan, tunjukkan kamu peduli, & bantu ia bicara ke orang dewasa tepercaya"],answer:2,explain:"Kamu bisa menjadi teman yang mendukung sekaligus menjembatani ke bantuan yang tepat.",hint:"Dengar + jembatani ke orang dewasa."},
{n:17,type:"tf",micro:"Minta bantuan = gagal?",q:"Benar atau Salah: Meminta bantuan berarti kamu sudah gagal menyelesaikan masalahmu sendiri.",answer:false,explain:"Sebaliknya, mengenali kapan butuh bantuan & mencarinya adalah keterampilan hidup yang penting, bukan kegagalan.",hint:"Keterampilan, bukan kegagalan."},
{n:18,type:"mcq",micro:"Layanan bantuan",q:"Selain orang tua & guru, sumber bantuan lain untuk masalah perasaan yang berat bisa berupa...",options:["konselor sekolah, psikolog, puskesmas, atau layanan bantuan (hotline)","hanya mencari jawabannya di media sosial dari orang-orang yang tidak kamu kenal sama sekali","memendamnya sendirian sampai perasaan itu hilang dengan sendirinya seiring berjalannya waktu"],answer:0,explain:"Ada orang & layanan khusus yang terlatih membantu; orang dewasa tepercaya bisa membantumu menghubunginya.",hint:"Konselor, psikolog, layanan bantuan."},
{n:19,type:"order",micro:"Meminta bantuan dengan jelas",q:"Urutkan langkah meminta bantuan dengan jelas:",items:["Kenali apa masalahnya & apa yang kamu butuhkan","Pilih orang yang tepat untuk masalah itu","Pilih waktu & tempat yang cukup tenang","Sampaikan masalah & permintaanmu secara langsung"],answer:[0,1,2,3],explain:"Kenali kebutuhan, pilih orang, pilih waktu, lalu sampaikan dengan jelas.",hint:"Tahu kebutuhan dulu, sampaikan terakhir."},
{n:20,type:"mcq",micro:"Ringkasan",q:"Inti bab ini adalah...",options:["teman yang baik selalu merahasiakan segalanya bahkan ketika temannya sedang dalam bahaya","meminta bantuan itu wajar & berani, & menjaga teman berarti mengajak orang dewasa saat masalah serius","kamu harus menyelesaikan semua masalahmu sendiri tanpa melibatkan orang lain dalam keadaan apa pun"],answer:1,explain:"Meminta & memberi bantuan adalah bagian dari hubungan yang sehat & menjaga keselamatan.",hint:"Berani minta bantuan + jaga teman."},
{n:21,type:"classify",micro:"Siapa yang menangani",q:"Kelompokkan setiap situasi:",items:["Lupa cara mengerjakan satu soal PR","Bertengkar kecil dengan teman lalu bingung minta maaf","Teman bercerita ada yang menyakitinya di rumah","Merasa sangat putus asa berhari-hari & sulit tidur"],groups:["Bisa dicoba sendiri / tanya teman","Perlu orang dewasa tepercaya"],answer:{"Bisa dicoba sendiri / tanya teman":["Lupa cara mengerjakan satu soal PR","Bertengkar kecil dengan teman lalu bingung minta maaf"],"Perlu orang dewasa tepercaya":["Teman bercerita ada yang menyakitinya di rumah","Merasa sangat putus asa berhari-hari & sulit tidur"]},explain:"Masalah kecil sehari-hari bisa dicoba sendiri atau dengan teman; hal yang menyangkut keselamatan & perasaan yang sangat berat perlu orang dewasa tepercaya.",hint:"Keselamatan & perasaan berat = orang dewasa."},
{n:22,type:"mcq",micro:"Hambatan: takut kena marah",q:"Kamu ragu bercerita karena takut dimarahi. Cara berpikir yang membantu:",options:["'Lebih baik aku diam saja selamanya supaya tidak ada yang marah dan masalahnya tidak membesar'","'Berarti masalahku memang tidak penting, jadi tidak ada gunanya dibicarakan kepada siapa pun'","'Orang dewasa yang tepat lebih peduli pada keselamatanku daripada mencari siapa yang salah'"],answer:2,explain:"Fokus orang dewasa tepercaya adalah membantu, bukan menghukum; bila satu orang bereaksi buruk, cari yang lain.",hint:"Mereka peduli keselamatanmu."},
{n:23,type:"mcq",micro:"Hambatan: merasa jadi beban",q:"Pikiran 'aku hanya akan membebani mereka' sebaiknya diganti dengan...",options:["'Orang yang menyayangiku ingin tahu kalau aku kesulitan'","'Semua orang terlalu sibuk dengan urusan mereka sendiri sehingga tidak ada yang punya waktu untukku'","'Aku memang tidak layak dibantu oleh siapa pun karena masalahku terlalu kecil dan merepotkan'"],answer:0,explain:"Orang yang peduli justru ingin dilibatkan saat kamu kesulitan.",hint:"Mereka ingin tahu."},
{n:24,type:"tf",micro:"Janji rahasia & bahaya",q:"Benar atau Salah: Kalau seorang teman dalam bahaya, janji 'aku tidak akan bilang siapa-siapa' tidak lagi mengikat, karena keselamatannya lebih penting.",answer:true,explain:"Menjaga teman tetap aman lebih penting daripada menepati janji rahasia dalam situasi berbahaya.",hint:"Keselamatan mengalahkan janji rahasia."},
{n:25,type:"mcq",micro:"Tanda peringatan pada diri sendiri",q:"Manakah tanda pada dirimu sendiri yang sebaiknya kamu ceritakan ke orang dewasa tepercaya?",options:["kamu ingin mengganti gaya rambutmu menjadi lebih pendek setelah liburan sekolah nanti","kamu sering merasa hampa, tidak berharga, atau berpikir ingin menghilang","kamu merasa bosan pada satu pelajaran tertentu karena gurunya menjelaskan terlalu lama"],answer:1,explain:"Perasaan hampa atau berpikir ingin menghilang yang menetap adalah sinyal untuk segera mencari bantuan orang dewasa.",hint:"Perasaan gelap yang menetap = cerita."},
{n:26,type:"mcq",micro:"Mendengarkan teman",q:"Kalimat yang menunjukkan kamu mendengarkan teman yang sedih:",options:["'Ah, itu sih tidak seberapa dibanding masalah yang pernah kualami dulu, jadi tidak perlu sedih'","'Sudah, lupakan saja semuanya, nanti juga hilang sendiri tanpa perlu kamu pikirkan terus-menerus'","'Kedengarannya berat sekali. Aku di sini. Mau cerita lebih banyak?'"],answer:2,explain:"Mengakui perasaannya & menunjukkan kamu hadir membuka ruang bercerita.",hint:"Akui perasaan + tawarkan hadir."},
{n:27,type:"mcq",micro:"Bukan menyimpan sendiri",q:"Setelah mendengar cerita berat dari teman, kamu sebaiknya...",options:["mengajaknya bersama-sama bicara ke orang dewasa tepercaya, & juga menceritakannya ke orang dewasamu sendiri","menyimpannya sendirian dan memikirkannya setiap malam sampai kamu sendiri merasa sangat lelah","langsung menyebarkannya kepada teman-teman lain supaya mereka ikut membantu memikirkan jalan keluarnya"],answer:0,explain:"Melibatkan orang dewasa membantu temanmu & juga meringankan bebanmu sebagai pendengar.",hint:"Ajak ke orang dewasa, jangan pikul sendiri."},
{n:28,type:"tf",micro:"Satu orang dewasa menolak",q:"Benar atau Salah: Kalau orang dewasa pertama yang kamu ceritakan tidak menanggapi serius, sebaiknya kamu menyerah & tidak bercerita ke siapa pun lagi.",answer:false,explain:"Sebaliknya, kalau satu orang tidak membantu, ceritakan ke orang dewasa tepercaya lain sampai ada yang menanggapi.",hint:"Coba orang dewasa lain, jangan berhenti."},
{n:29,type:"mcq",micro:"Meminta bantuan praktis",q:"Kamu kewalahan mengerjakan tugas kelompok karena anggota lain tidak membantu. Langkah:",options:["membiarkan tugas tidak selesai tanpa memberi tahu siapa pun","bicara ke guru tentang situasinya & minta saran pembagian tugas","mengerjakan semuanya sendiri sambil kesal"],answer:1,explain:"Memberi tahu guru lebih awal memberi kesempatan masalah dibereskan dengan adil.",hint:"Beri tahu guru lebih awal."},
{n:30,type:"mcq",micro:"Membedakan mendengar & menasihati",q:"Sebelum memberi saran pada teman yang curhat, sebaiknya kamu...",options:["langsung memberi lima solusi sekaligus supaya masalahnya cepat selesai tanpa perlu bertanya","menyuruhnya melakukan apa yang menurutmu paling benar tanpa mendengarkan perasaannya lebih dulu","tanya dulu, 'Kamu ingin didengar saja, atau ingin dibantu pikirkan jalan keluar?'"],answer:2,explain:"Menanyakan apa yang ia butuhkan membuat dukunganmu lebih tepat.",hint:"Tanya: didengar atau dibantu berpikir?"},
{n:31,type:"mcq",micro:"Bercerita ke konselor sekolah",q:"Konselor sekolah adalah orang yang...",options:["bertugas membantu siswa dengan masalah belajar, pertemanan, & perasaan","hanya bertugas menghukum siswa yang nakal dan melaporkan mereka kepada orang tua","tidak boleh ditemui oleh siswa kecuali siswa itu dipanggil lebih dulu oleh gurunya"],answer:0,explain:"Konselor sekolah adalah sumber bantuan yang bisa kamu datangi sendiri.",hint:"Membantu, bukan menghukum."},
{n:32,type:"tf",micro:"Tanda bahaya butuh tindakan cepat",q:"Benar atau Salah: Jika teman berbicara tentang ingin menyakiti diri sendiri atau mengakhiri hidupnya, kamu harus segera memberi tahu orang dewasa tepercaya, hari itu juga.",answer:true,explain:"Ucapan tentang menyakiti diri selalu ditanggapi serius & segera; jangan menundanya atau merahasiakannya.",hint:"Segera, hari itu juga."},
{n:33,type:"mcq",micro:"Menemani teman ke orang dewasa",q:"Temanmu takut bercerita ke guru sendirian. Kamu bisa membantu dengan...",options:["bercerita sendiri lalu menyebut namanya tanpa izin, kecuali ia dalam bahaya","menawarkan menemaninya saat bicara ke guru","memaksanya masuk ke ruang guru"],answer:1,explain:"Menemani membuat langkah meminta bantuan terasa lebih aman.",hint:"Temani dia."},
{n:34,type:"mcq",micro:"Kata-kata untuk memulai",q:"Kalimat pembuka yang baik saat kamu ingin bercerita tentang sesuatu yang berat:",options:["'Ah, tidak jadi deh, tidak penting kok, lupakan saja apa yang tadi mau kuceritakan.'","menunggu sampai orang lain menebak sendiri apa yang sedang mengganggu pikiranmu selama ini","'Ada hal yang mengganggu pikiranku & aku butuh bantuan memikirkannya. Boleh cerita sebentar?'"],answer:2,explain:"Kalimat pembuka yang jujur & langsung memudahkan orang dewasa memberi perhatian penuh.",hint:"Sebutkan bahwa kamu butuh bantuan."},
{n:35,type:"mcq",micro:"Menghargai keberanian teman",q:"Saat teman memberanikan diri bercerita padamu tentang masalah berat, respons pertama yang baik:",options:["'Terima kasih sudah cerita padaku. Itu berani. Aku ikut memikirkannya bersamamu.'","'Kok baru cerita sekarang? Kenapa tidak dari kemarin-kemarin saja kamu memberi tahu aku?'","'Jangan cerita ke orang lain ya, ini rahasia kita berdua saja apa pun yang terjadi nanti.'"],answer:0,explain:"Menghargai keberaniannya membuat ia merasa aman & lebih terbuka pada bantuan; jangan berjanji merahasiakan hal yang menyangkut keselamatan.",hint:"Hargai keberaniannya."},
{n:36,type:"order",micro:"Membantu teman yang berbicara soal menyakiti diri",q:"Urutkan langkah bila teman berkata ia berpikir menyakiti dirinya:",items:["Tetap tenang & dengarkan dengan serius, jangan menghakimi","Katakan kamu peduli & ia tidak sendirian","Jangan berjanji merahasiakannya; jelaskan kalian butuh bantuan orang dewasa","Segera libatkan orang dewasa tepercaya, & jangan tinggalkan ia sendirian bila situasinya mendesak"],answer:[0,1,2,3],explain:"Dengarkan, tunjukkan kepedulian, jangan janjikan rahasia, & segera libatkan orang dewasa.",hint:"Tenang & dengar dulu, orang dewasa segera."},
{n:37,type:"mcq",micro:"Menjaga diri sebagai penolong",q:"Setelah membantu teman melewati masa sulit, kamu sebaiknya...",options:["berhenti peduli pada siapa pun supaya kamu tidak lagi merasa lelah memikirkan masalah orang lain","bercerita ke orang dewasamu sendiri & melakukan hal yang menenangkanmu","memendam semuanya sendirian dan merasa harus selalu kuat supaya tidak merepotkan orang lain"],answer:1,explain:"Penolong juga butuh dukungan; berbagi beban dengan orang dewasa menjaga kamu tetap sehat.",hint:"Kamu juga butuh dukungan."},
{n:38,type:"open",micro:"Skrip meminta bantuan",q:"Tulis kalimat yang bisa kamu pakai untuk meminta bantuan orang dewasa tentang sesuatu yang membuatmu cemas belakangan ini.",explain:"Menyiapkan kalimat lebih dulu membuat langkah pertama terasa lebih ringan.",hint:"Sebut perasaan + situasi + permintaan bantuan.",sample:"Bu, belakangan aku sering susah tidur & merasa cemas setiap mau berangkat sekolah karena ada masalah dengan beberapa teman. Aku belum tahu harus bagaimana. Boleh aku cerita & minta bantuan Ibu memikirkan langkahnya?"},
{n:39,type:"mcq",micro:"Bukan menyebar cerita",q:"Perbedaan antara 'mencari bantuan untuk teman' dan 'menyebarkan gosip' adalah...",options:["keduanya sama saja","mencari bantuan berarti menceritakannya ke semua teman sekelas","mencari bantuan dilakukan ke orang dewasa yang bisa menolong, dengan niat menjaga temanmu"],answer:2,explain:"Membawa masalah ke orang dewasa yang tepat adalah menolong; menceritakannya ke banyak orang untuk seru-seruan adalah menyakiti.",hint:"Ke orang yang bisa menolong, dengan niat menjaga."},
{n:40,type:"tf",micro:"Teman marah karena kamu cerita",q:"Benar atau Salah: Jika temanmu marah karena kamu memberi tahu orang dewasa saat ia dalam bahaya, itu berarti kamu telah melakukan hal yang salah.",answer:false,explain:"Sebaliknya, menjaga temanmu tetap aman adalah tindakan yang benar & peduli, meski ia marah untuk sementara.",hint:"Menjaga ia aman = tindakan benar."},
{n:41,type:"mcq",micro:"Meminta bantuan guru",q:"Kamu tertinggal jauh dalam satu pelajaran. Cara meminta bantuan:",options:["temui guru setelah kelas: 'Pak, saya tertinggal di beberapa bab. Bisa minta saran cara mengejarnya?'","diam saja dan berharap nilai pelajaran itu akan membaik dengan sendirinya seiring berjalannya waktu","menyalin PR milik temanmu setiap hari supaya nilai tugasmu tetap terlihat baik di mata guru"],answer:0,explain:"Meminta saran konkret pada guru membuka jalan bantuan, misalnya jam tambahan atau materi latihan.",hint:"Minta saran cara mengejar."},
{n:42,type:"mcq",micro:"Meminta dukungan emosional",q:"Cara meminta dukungan emosional dari orang tua:",options:["marah-marah kepada mereka lalu mengurung diri di kamar sampai mereka mengerti sendiri perasaanmu","'Aku lagi sedih berat soal ini. Aku tidak butuh solusi dulu, aku cuma butuh didengar & dipeluk.'","berharap mereka bisa mengetahuinya sendiri tanpa kamu katakan apa pun tentang perasaanmu itu"],answer:1,explain:"Menyebut apa yang kamu butuhkan (didengar, ditemani) membantu mereka mendukung dengan tepat.",hint:"Sebutkan yang kamu butuhkan."},
{n:43,type:"mcq",micro:"Kata-kata untuk teman yang berjuang",q:"Temanmu terlihat murung berhari-hari. Kalimat yang membantu:",options:["'Kamu kenapa sih murung terus begitu? Jangan lebay, semua orang juga punya masalah masing-masing.'","pura-pura tidak melihatnya dan menunggu sampai ia sendiri yang datang dan menceritakan masalahnya","'Aku memperhatikan kamu kelihatan sedih akhir-akhir ini. Aku peduli. Mau cerita? Kalau berat, kita bisa cerita ke Bu guru bareng.'"],answer:2,explain:"Menyebut yang kamu lihat, menyatakan kepedulian, & menawarkan menjembatani ke orang dewasa adalah dukungan yang kuat.",hint:"Aku lihat, aku peduli, ayo cerita bareng."},
{n:44,type:"tf",micro:"Boleh cerita ke lebih dari satu orang",q:"Benar atau Salah: Kamu boleh menceritakan masalah yang sama ke lebih dari satu orang dewasa tepercaya bila yang pertama belum bisa membantu.",answer:true,explain:"Terus mencari sampai mendapat bantuan yang tepat adalah hal yang wajar & dianjurkan.",hint:"Boleh, sampai dapat bantuan tepat."},
{n:45,type:"mcq",micro:"Membantu tanpa memikul semua",q:"Temanmu sangat bergantung padamu untuk semua masalahnya sampai kamu kelelahan. Langkah sehat:",options:["tetap peduli, tapi dorong ia bicara ke konselor atau orang dewasa & jaga waktu istirahatmu","memutuskan pertemanan dengannya tanpa memberi penjelasan apa pun supaya kamu bisa beristirahat","menuruti semua permintaannya sambil diam-diam merasa kesal dan semakin kelelahan setiap harinya"],answer:0,explain:"Kamu bisa mendukung sambil mengarahkan ke bantuan yang lebih besar & menjaga kebutuhanmu sendiri.",hint:"Peduli + arahkan ke bantuan + jaga diri."},
{n:46,type:"mcq",micro:"Saat tidak tahu harus minta ke siapa",q:"Kamu punya masalah berat tapi bingung harus cerita ke siapa. Langkah pertama:",options:["menyimpulkan bahwa tidak ada seorang pun yang bisa membantu masalahmu sehingga tidak usah bercerita","mulai dari satu orang dewasa mana pun yang terasa paling aman, misalnya wali kelas atau konselor","menunggu sampai ada orang yang bertanya sendiri kepadamu tentang apa yang sedang kamu rasakan"],answer:1,explain:"Tidak perlu orang yang sempurna; mulai dari yang terasa paling aman, mereka bisa mengarahkan ke bantuan lain.",hint:"Mulai dari yang paling aman."},
{n:47,type:"mcq",micro:"Menggunakan layanan bantuan",q:"Layanan bantuan (hotline) atau konselor berguna karena...",options:["hanya diperuntukkan bagi orang dewasa, sedangkan anak-anak dan remaja tidak boleh memakainya","membuat masalah yang kamu ceritakan jadi lebih buruk dan menyebar ke banyak orang lain","dilayani orang yang terlatih mendengar & membantu, & bisa diakses saat butuh"],answer:2,explain:"Ada layanan yang dirancang khusus untuk mendengarkan & membantu; orang dewasa tepercaya bisa membantumu menghubunginya.",hint:"Orang terlatih, bisa diakses saat butuh."},
{n:48,type:"tf",micro:"Menunggu sampai parah?",q:"Benar atau Salah: Sebaiknya kamu menunggu sampai suatu masalah menjadi sangat parah sebelum meminta bantuan.",answer:false,explain:"Sebaliknya, meminta bantuan sejak dini biasanya membuat masalah lebih mudah diatasi & mencegahnya membesar.",hint:"Minta lebih awal, bukan menunggu parah."},
{n:49,type:"mcq",micro:"Menanggapi 'jangan bilang siapa-siapa'",q:"Teman berkata 'aku cerita ini tapi janji jangan bilang siapa-siapa' lalu menceritakan sesuatu yang berbahaya. Responsmu:",options:["'Aku sayang kamu, karena itu aku tidak bisa janji merahasiakan hal yang bisa membahayakanmu. Ayo kita cari bantuan.'","'Oke, aku janji tidak akan memberi tahu siapa pun, apa pun yang kamu ceritakan nanti kepadaku.'","langsung menceritakannya kepada teman-teman lain supaya mereka ikut membantu mengawasi dirinya"],answer:0,explain:"Jujur bahwa kamu tidak bisa merahasiakan bahaya, lalu ajak mencari bantuan, adalah respons yang menjaga temanmu.",hint:"Tidak janji rahasia untuk bahaya; ajak cari bantuan."},
{n:50,type:"mcq",micro:"Setelah meminta bantuan",q:"Setelah kamu meminta bantuan & mendapat saran, langkah baik berikutnya:",options:["menganggap bahwa masalahmu pasti akan hilang sendiri sekarang setelah kamu menceritakannya","coba jalankan satu langkah yang disepakati & kabari orang itu bagaimana hasilnya","mengabaikan saran yang diberikan karena kamu sudah merasa lega setelah selesai bercerita"],answer:1,explain:"Menindaklanjuti & memberi kabar menjaga bantuan tetap berjalan.",hint:"Jalankan + kabari hasilnya."},
{n:51,type:"mcq",micro:"Skenario: teman dilukai di rumah",q:"Teman bercerita bahwa ada anggota keluarganya yang memukulinya. Yang harus kamu lakukan:",options:["menyuruhnya bersabar dan tidak membuat masalah supaya keadaan di rumahnya tidak bertambah buruk","merahasiakannya dari semua orang karena ia sendiri yang memintamu untuk tidak memberi tahu siapa pun","percayai ceritanya, katakan itu bukan salahnya, & segera bantu ia bicara ke guru atau konselor"],answer:2,explain:"Kekerasan di rumah selalu perlu melibatkan orang dewasa yang bisa melindungi; ini bukan rahasia yang boleh disimpan.",hint:"Percaya, bukan salahnya, libatkan orang dewasa."},
{n:52,type:"order",micro:"Membawa masalah ke guru",q:"Urutkan langkah membawa masalah temanmu ke guru:",items:["Ajak temanmu bicara & sepakati kalian butuh bantuan","Pilih guru atau konselor yang kalian percaya","Minta waktu bicara berdua atau bertiga di tempat tenang","Ceritakan situasinya dengan jujur & minta bantuan langkah berikutnya"],answer:[0,1,2,3],explain:"Sepakat dulu, pilih orang, minta waktu, lalu ceritakan dengan jujur.",hint:"Sepakat dulu, cerita terakhir."},
{n:53,type:"mcq",micro:"Skenario: kamu merasa sendirian",q:"Kamu merasa sangat sedih & sendirian belakangan ini. Langkah pertama yang sehat:",options:["ceritakan pada satu orang dewasa tepercaya bahwa kamu sedang tidak baik-baik saja","menyimpannya sendirian sampai perasaan itu mereda dengan sendirinya tanpa memberi tahu siapa pun","menyimpulkan bahwa tidak akan ada seorang pun yang mengerti perasaanmu sehingga tidak perlu bercerita"],answer:0,explain:"Menyuarakan bahwa kamu sedang kesulitan pada orang dewasa tepercaya adalah langkah pertama menuju bantuan.",hint:"Suarakan ke satu orang dewasa."},
{n:54,type:"mcq",micro:"Skenario: teman dirundung",q:"Temanmu dirundung setiap hari & memintamu tidak memberi tahu siapa pun. Yang tepat:",options:["membalas perundung itu dengan kekerasan supaya ia takut dan tidak berani mengganggu lagi","dukung ia & tetap bantu melaporkannya ke guru; perundungan yang dibiarkan biasanya makin parah","ikut diam saja karena temanmu sendiri yang meminta kamu untuk tidak memberi tahu siapa pun"],answer:1,explain:"Perundungan perlu diketahui orang dewasa agar bisa dihentikan; diam justru membuatnya berlanjut.",hint:"Laporkan; diam memperparah."},
{n:55,type:"mcq",micro:"Skenario: adik minta tolong",q:"Adikmu bercerita hal yang membuatmu khawatir tapi kamu tidak yakin harus bagaimana. Langkah:",options:["menyuruhnya tidak berlebihan karena menurutmu itu hanya hal kecil yang akan segera ia lupakan","menjanjikan kepadanya bahwa kamu akan menyelesaikannya sendirian secara diam-diam tanpa memberi tahu siapa pun","dengarkan dengan tenang, lalu sampaikan ke orang tua atau orang dewasa tepercaya"],answer:2,explain:"Saat ragu, melibatkan orang dewasa tepercaya adalah pilihan yang aman.",hint:"Dengar, lalu libatkan orang dewasa."},
{n:56,type:"open",micro:"Rencana bantuanmu",q:"Bayangkan seorang teman datang padamu dengan masalah yang berat. Tulis tiga hal yang akan kamu lakukan.",explain:"Merencanakan lebih dulu membuat kamu lebih siap menjadi teman yang menolong dengan tepat.",hint:"Dengar, tunjukkan peduli, jembatani ke orang dewasa.",sample:"Satu, aku akan mendengarkan sungguh-sungguh tanpa memotong atau menghakimi. Dua, aku akan bilang aku peduli & dia tidak sendirian. Tiga, aku akan mengajak dia bicara ke wali kelas atau konselor, & menemani kalau dia mau; kalau dia dalam bahaya, aku tetap akan cerita ke orang dewasa meski dia minta dirahasiakan."},
{n:57,type:"mcq",micro:"Skenario: orang dewasa pertama tak menanggapi",q:"Kamu sudah cerita ke satu guru tapi ia terlihat tidak menganggapnya penting. Langkah berikutnya:",options:["ceritakan ke orang dewasa tepercaya lain, misalnya konselor, orang tua, atau guru lain","menyerah dan menyimpulkan bahwa tidak ada seorang pun yang peduli pada masalah yang kamu hadapi","marah kepada guru itu di depan kelas supaya semua orang tahu bahwa ia tidak mau mendengarmu"],answer:0,explain:"Satu tanggapan yang kurang tepat bukan akhir; teruslah sampai kamu mendapat bantuan yang serius.",hint:"Cerita ke orang dewasa lain."},
{n:58,type:"tf",micro:"Penolong butuh cerita juga",q:"Benar atau Salah: Setelah menolong teman melewati masalah berat, kamu juga boleh & sebaiknya menceritakan perasaanmu ke orang dewasa tepercaya.",answer:true,explain:"Mendengar cerita berat bisa membebani; berbagi dengan orang dewasa menjaga kamu tetap sehat.",hint:"Kamu juga boleh cerita."},
{n:59,type:"mcq",micro:"Skenario: tugas menumpuk",q:"Kamu kewalahan karena banyak tugas & kegiatan sampai sulit tidur. Langkah sehat:",options:["menyerah pada semua tugas dan kegiatan sekaligus lalu berhenti mengerjakan apa pun mulai sekarang","bicara ke orang tua atau wali kelas untuk membantu mengatur prioritas & mungkin mengurangi beban","memaksakan diri terus mengerjakan semuanya tanpa istirahat sampai tubuhmu benar-benar jatuh sakit"],answer:1,explain:"Meminta bantuan mengatur beban lebih baik daripada memaksakan diri hingga kelelahan.",hint:"Minta bantuan atur prioritas."},
{n:60,type:"mcq",micro:"Skenario: teman menjauh & murung",q:"Teman dekatmu tiba-tiba berhenti ikut kegiatan & terlihat murung. Yang bisa kamu lakukan:",options:["menganggap bahwa ia hanya sedang malas dan akan kembali seperti biasa dengan sendirinya nanti","membicarakannya dengan teman-teman lain di belakangnya supaya kalian bisa menebak-nebak penyebabnya","hubungi ia dengan hangat, tanyakan kabarnya, & bila kekhawatiranmu berlanjut, sampaikan ke orang dewasa tepercaya"],answer:2,explain:"Menjangkau dengan tulus & melibatkan orang dewasa bila perlu bisa sangat berarti bagi teman yang sedang berjuang.",hint:"Jangkau + libatkan orang dewasa bila khawatir."},
{n:61,type:"mcq",micro:"Mengapa rahasia keselamatan berbeda",q:"Rahasia tentang kejutan ulang tahun & rahasia tentang seseorang yang terluka berbeda karena...",options:["yang kedua menyangkut keselamatan, sehingga orang dewasa perlu tahu untuk membantu","keduanya sebenarnya sama saja sehingga kamu boleh menyimpan keduanya sebagai rahasia selamanya","yang pertama jauh lebih penting untuk disimpan karena menyangkut perasaan banyak orang sekaligus"],answer:0,explain:"Rahasia yang menyenangkan & sementara berbeda dari rahasia yang menyangkut bahaya atau luka.",hint:"Menyangkut keselamatan atau tidak."},
{n:62,type:"mcq",micro:"Janji yang tak seharusnya dibuat",q:"Sebelum teman bercerita, ia minta kamu berjanji merahasiakan apa pun. Respons bijak:",options:["'Kalau begitu sebaiknya kamu jangan cerita apa pun saja kepadaku, supaya aku tidak terbebani.'","'Aku akan mendengarkan & menjaga ini sebaik mungkin, tapi kalau menyangkut keselamatanmu, aku mungkin perlu bantuan orang dewasa.'","'Iya, aku janji apa pun yang kamu ceritakan akan menjadi rahasia kita berdua selamanya.'"],answer:1,explain:"Jujur sejak awal tentang batas kerahasiaan lebih baik daripada berjanji lalu terpaksa mengingkarinya.",hint:"Jujurkan batas rahasianya di awal."},
{n:63,type:"mcq",micro:"Rasa bersalah yang keliru",q:"Jika kamu sudah melibatkan orang dewasa untuk menolong teman & teman itu kecewa, rasa bersalah yang muncul...",options:["adalah bukti kamu telah mengkhianatinya","berarti kamu harus berjanji tidak akan pernah cerita lagi","wajar dirasakan, tapi keputusanmu untuk menjaganya tetap yang benar"],answer:2,explain:"Perasaan tidak enak bisa muncul, tetapi melindungi keselamatan seseorang adalah pilihan yang tepat.",hint:"Rasa bersalah wajar, keputusannya tetap benar."},
{n:64,type:"tf",micro:"Kamu penyebab masalah teman?",q:"Benar atau Salah: Jika seorang teman sedang mengalami masa yang sangat berat, itu adalah tanggung jawab & kesalahanmu untuk menyelesaikannya sendirian.",answer:false,explain:"Sebaliknya, kamu bisa mendukung, tetapi masalah besar butuh orang dewasa & kadang tenaga profesional; itu bukan beban yang harus kamu pikul sendiri.",hint:"Dukung ya, memikul sendiri tidak."},
{n:65,type:"mcq",micro:"Peran profesional",q:"Psikolog, konselor, atau dokter berperan untuk...",options:["membantu masalah perasaan atau kesehatan yang butuh keahlian khusus","menggantikan peran teman dan keluarga sepenuhnya sehingga kamu tidak lagi perlu bercerita kepada mereka","dihubungi hanya kalau semua cara lain sudah gagal total dan keadaannya sudah sangat parah"],answer:0,explain:"Sama seperti kita ke dokter untuk tubuh, ada ahli untuk membantu pikiran & perasaan; meminta bantuan mereka adalah hal yang wajar.",hint:"Ahli untuk hal yang butuh keahlian khusus."},
{n:66,type:"mcq",micro:"Mencocokkan bantuan dengan masalah",q:"Untuk kesulitan memahami pelajaran, sumber bantuan yang paling tepat biasanya...",options:["tidak ada, harus dipikirkan sendiri","guru, tutor, atau teman yang paham materi itu","layanan darurat"],answer:1,explain:"Mencocokkan jenis masalah dengan penolong yang tepat membuat bantuan lebih efektif.",hint:"Masalah belajar -> guru/tutor."},
{n:67,type:"mcq",micro:"Mengetahui batas diri",q:"Tanda bahwa sebuah masalah sudah di luar yang bisa kamu tangani sendiri:",options:["kamu perlu berpikir sebentar dan mencari tahu lebih dulu sebelum akhirnya bisa menyelesaikannya sendiri","kamu merasa sedikit gugup di awal tetapi perasaan itu hilang setelah kamu mulai mengerjakannya","masalah itu terus mengganggu tidur, suasana hati, atau membuatmu merasa tidak aman"],answer:2,explain:"Bila sebuah masalah mulai mengganggu fungsi sehari-hari atau rasa aman, itu saatnya melibatkan orang dewasa.",hint:"Mengganggu tidur, mood, rasa aman."},
{n:68,type:"tf",micro:"Meminta bantuan berkali-kali",q:"Benar atau Salah: Wajar bila seseorang perlu meminta bantuan lebih dari sekali untuk masalah yang sama sebelum keadaan membaik.",answer:true,explain:"Pemulihan sering bertahap; meminta bantuan berulang bukan tanda gagal, melainkan bagian dari proses.",hint:"Bertahap itu normal."},
{n:69,type:"mcq",micro:"Menjaga kepercayaan teman",q:"Saat membawa masalah teman ke orang dewasa, cara menjaga kepercayaannya:",options:["beri tahu ia lebih dulu (bila aman) bahwa kamu akan mencari bantuan & mengapa","menceritakannya diam-diam & tidak pernah membahasnya lagi dengannya","menambah-nambahi cerita agar terdengar lebih serius"],answer:0,explain:"Sedapat mungkin bersikap terbuka dengan temanmu tentang langkah yang kamu ambil untuk menjaganya.",hint:"Beri tahu dia lebih dulu bila aman."},
{n:70,type:"order",micro:"Saat kamu sendiri kewalahan",q:"Urutkan langkah saat kamu merasa kewalahan & tidak tahu harus bagaimana:",items:["Akui pada diri sendiri bahwa kamu sedang tidak baik-baik saja","Pilih satu orang dewasa tepercaya untuk diajak bicara","Ceritakan apa yang kamu rasakan & alami sejujurnya","Sepakati satu langkah kecil berikutnya bersama mereka"],answer:[0,1,2,3],explain:"Akui, pilih orang, ceritakan, lalu sepakati langkah kecil bersama.",hint:"Akui dulu, langkah kecil terakhir."},
{n:71,type:"mcq",micro:"Mengapa menunda memperberat",q:"Menunda meminta bantuan untuk masalah perasaan sering membuatnya lebih berat karena...",options:["orang lain jadi lebih mudah membantu bila kita menunggu lama","masalah yang dipendam cenderung menumpuk & terasa makin sendirian","perasaan selalu hilang sendiri bila diabaikan"],answer:1,explain:"Berbagi lebih awal mencegah beban menumpuk & rasa terisolasi.",hint:"Dipendam = menumpuk & makin sendiri."},
{n:72,type:"mcq",micro:"Membedakan curhat & mencari bantuan",q:"Bercerita ke banyak teman tentang masalah beratmu tanpa melibatkan orang dewasa...",options:["selalu cukup untuk menyelesaikan masalah apa pun, termasuk yang menyangkut keselamatanmu sendiri","sama efektifnya dengan bicara kepada konselor yang sudah terlatih menangani masalah perasaan","bisa melegakan sesaat, tapi belum tentu membawa bantuan yang kamu butuhkan"],answer:2,explain:"Teman sebaya bisa mendukung, tetapi masalah berat tetap butuh orang dewasa atau profesional.",hint:"Lega sesaat belum tentu bantuan yang tepat."},
{n:73,type:"mcq",micro:"Menjadi teman yang aman untuk cerita",q:"Agar teman merasa aman bercerita padamu, kamu bisa...",options:["mendengar tanpa menghakimi, tidak menyebarkannya, & jujur soal kapan kamu perlu bantuan orang dewasa","berjanji merahasiakan apa pun yang ia ceritakan tanpa kecuali, bahkan bila ia sedang dalam bahaya","langsung memberi tahu semua orang tentang ceritanya agar masalahnya cepat selesai dan tidak membebani"],answer:0,explain:"Teman yang aman: mendengar, menjaga, & jujur tentang batas kerahasiaan demi keselamatan.",hint:"Dengar, jaga, jujur soal batas."},
{n:74,type:"open",micro:"Refleksi hambatan",q:"Apa satu hal yang selama ini membuatmu ragu meminta bantuan? Tulis satu kalimat untuk menjawab keraguan itu.",explain:"Menamai hambatan & menyiapkan jawabannya membuat langkah meminta bantuan terasa lebih mungkin.",hint:"Sebut hambatan + kalimat penyeimbangnya.",sample:"Aku ragu karena takut dianggap lemah atau cari perhatian. Jawabanku: meminta bantuan saat butuh justru menunjukkan aku mengenali diriku & cukup berani untuk jujur, & orang yang tepat tidak akan menghakimiku."},
{n:75,type:"tf",micro:"Orang dewasa selalu bisa langsung menyelesaikan?",q:"Benar atau Salah: Begitu kamu bercerita ke orang dewasa, semua masalah pasti langsung selesai seketika.",answer:false,explain:"Sebaliknya, bantuan sering butuh proses & beberapa langkah; yang penting kamu tidak lagi menghadapinya sendirian.",hint:"Proses, bukan sulap."},
{n:76,type:"mcq",micro:"Dukungan sebaya yang sehat",q:"Cara teman sebaya saling mendukung dengan sehat:",options:["saling melarang untuk bercerita kepada orang lain agar semua rahasia tetap aman di antara kalian","saling mendengar, mengingatkan untuk mencari bantuan orang dewasa saat perlu, & tidak menyimpan bahaya sebagai rahasia","berjanji untuk menjadi satu-satunya orang yang saling membantu tanpa melibatkan orang dewasa mana pun"],answer:1,explain:"Dukungan sebaya berharga bila tetap terhubung dengan bantuan orang dewasa untuk hal yang berat.",hint:"Saling dengar + tetap libatkan orang dewasa."},
{n:77,type:"mcq",micro:"Menghargai diri yang meminta bantuan",q:"Setelah berhasil meminta bantuan untuk sesuatu yang sulit, sikap yang sehat pada diri sendiri:",options:["menganggapnya hal yang memalukan dan berjanji pada diri sendiri untuk tidak mengulanginya lagi","merasa berutang budi yang tidak akan pernah bisa terbayar kepada orang yang membantumu selamanya","mengakui bahwa itu langkah berani & memuji diri karena melakukannya"],answer:2,explain:"Meminta bantuan adalah keterampilan yang patut dihargai, bukan disesali.",hint:"Itu langkah berani."},
{n:78,type:"mcq",micro:"Ketika kamu tidak yakin ini 'cukup serius'",q:"Kamu ragu apakah masalahmu 'cukup serius' untuk diceritakan. Panduan yang membantu:",options:["kalau itu terus mengganggumu, itu sudah cukup alasan untuk bercerita ke orang dewasa tepercaya","tunggu sampai kamu benar-benar sudah tidak tahan lagi baru kemudian menceritakannya kepada orang dewasa","hanya masalah yang sangat besar dan jelas-jelas berbahaya yang boleh diceritakan kepada orang dewasa"],answer:0,explain:"Kamu tidak perlu menunggu masalah 'cukup parah'; mengganggu pikiranmu saja sudah alasan yang sah.",hint:"Kalau mengganggumu, itu cukup."},
{n:79,type:"mcq",micro:"Membantu teman menemukan kata-kata",q:"Temanmu ingin cerita ke orang tuanya tapi tidak tahu cara memulai. Kamu bisa membantu dengan...",options:["menceritakannya sendiri kepada orang tuanya tanpa izin darinya, walaupun ia tidak dalam bahaya","berlatih bersama kalimat pembukanya, misalnya 'Bu, aku butuh cerita sesuatu yang berat'","menyuruhnya diam saja kalau memang sulit memulai, karena nanti juga masalahnya akan reda sendiri"],answer:1,explain:"Berlatih kalimat pembuka membuat percakapan yang menakutkan terasa lebih mungkin.",hint:"Latih kalimat pembukanya bersama."},
{n:80,type:"mcq",micro:"Tindak lanjut kepedulian",q:"Setelah temanmu mulai mendapat bantuan dari orang dewasa, peranmu sebagai teman:",options:["menganggap tugasmu sudah selesai sepenuhnya lalu menjauh darinya supaya tidak mengganggu prosesnya","terus-menerus membahas masalahnya setiap kali kalian bertemu supaya ia tidak pernah melupakannya","tetap hadir sebagai teman biasa: mengobrol, bermain, menanyakan kabar"],answer:2,explain:"Kehadiran yang hangat & normal tetap berarti sementara orang dewasa menangani hal yang berat.",hint:"Tetap jadi teman biasa yang hangat."},
{n:81,type:"mcq",micro:"Skenario: teman bicara ingin mengakhiri hidup",q:"Temanmu berkata pelan, 'Kadang aku merasa lebih baik aku tidak ada,' lalu memintamu berjanji diam. Yang harus kamu lakukan:",options:["tetap bersamanya, katakan kamu peduli, jangan berjanji merahasiakan, & segera libatkan orang dewasa tepercaya hari itu juga","berjanji akan diam dan berharap ia akan membaik sendiri tanpa melibatkan siapa pun juga","mengubah topik pembicaraan supaya suasana tidak menjadi berat dan ia tidak merasa canggung"],answer:0,explain:"Ucapan seperti ini selalu ditanggapi serius & segera; temani ia & bawa ke orang dewasa tepercaya tanpa menunda.",hint:"Temani, jangan janji diam, orang dewasa segera."},
{n:82,type:"tf",micro:"Menanggapi serius meski ragu",q:"Benar atau Salah: Bahkan bila kamu tidak yakin temanmu 'serius' saat berbicara tentang menyakiti diri, kamu tetap sebaiknya memberi tahu orang dewasa tepercaya.",answer:true,explain:"Lebih baik menanggapi dengan serius & keliru daripada mengabaikan & menyesal; biarkan orang dewasa menilai lebih lanjut.",hint:"Ragu pun, tetap beri tahu."},
{n:83,type:"mcq",micro:"Skenario: adik dibully di sekolah lain",q:"Adikmu bercerita ia dipukul kakak kelas & takut melapor. Langkah:",options:["menganggap bahwa ia hanya melebih-lebihkan ceritanya dan hal itu hanya main-main biasa saja","dengarkan, yakinkan itu bukan salahnya, & bantu ia menceritakannya ke orang tua atau guru","menyuruhnya melawan balik sendirian supaya kakak kelas itu takut dan tidak berani mengulanginya"],answer:1,explain:"Kekerasan perlu diketahui orang dewasa yang bisa melindungi; menemani adik melapor sangat membantu.",hint:"Dengar, bukan salahnya, bawa ke orang dewasa."},
{n:84,type:"mcq",micro:"Skenario: kamu ingin menyerah pada semuanya",q:"Kamu merasa sangat lelah & berpikir 'tidak ada gunanya lagi'. Langkah paling penting sekarang:",options:["menunggu beberapa minggu lagi untuk melihat apakah perasaan itu akan membaik dengan sendirinya","menyimpannya sendiri karena tidak ingin membuat orang lain khawatir atau ikut merasa sedih","ceritakan perasaan ini kepada orang dewasa tepercaya secepat mungkin, hari ini"],answer:2,explain:"Perasaan seperti ini adalah alasan untuk segera mencari bantuan orang dewasa atau layanan bantuan, bukan untuk ditanggung sendiri.",hint:"Cerita ke orang dewasa hari ini."},
{n:85,type:"mcq",micro:"Skenario: orang tua sedang sangat sibuk",q:"Kamu butuh bantuan tapi orang tuamu sedang sangat sibuk & lelah. Yang bisa kamu lakukan:",options:["katakan 'Aku tahu Ayah lelah, tapi ada hal penting yang perlu kuceritakan. Bisa kita bicara nanti malam?'","memutuskan untuk tidak jadi bercerita sama sekali karena orang tuamu tampak terlalu sibuk dan lelah","menunggu sampai mereka bertanya sendiri kepadamu apa yang sedang mengganggu pikiranmu selama ini"],answer:0,explain:"Meminta waktu khusus dengan jujur menandakan ini penting & biasanya akan didengar.",hint:"Minta waktu khusus dengan jujur."},
{n:86,type:"mcq",micro:"Skenario: teman minta bantuan tugas terus",q:"Teman meminta kamu mengerjakan tugasnya hampir setiap hari sampai kamu kelelahan. Respons sehat:",options:["tiba-tiba menolak membantu sama sekali lalu memarahinya karena sudah terlalu sering memintamu","'Aku mau bantu menjelaskan caranya, tapi aku tidak bisa mengerjakannya untukmu. Kalau kesulitan terus, ayo bilang ke guru.'","terus mengerjakan tugasnya setiap hari supaya ia tidak kecewa walaupun kamu sendiri sudah kelelahan"],answer:1,explain:"Membantu belajar berbeda dari mengambil alih; mengarahkan ke guru adalah bantuan yang lebih nyata.",hint:"Bantu memahami, bukan mengambil alih."},
{n:87,type:"mcq",micro:"Skenario: kamu sudah cerita tapi masih berat",q:"Kamu sudah cerita ke konselor tapi masih merasa berat beberapa hari kemudian. Yang sebaiknya kamu lakukan:",options:["berhenti mencari bantuan karena merasa sudah pernah bercerita sekali dan tidak perlu mengulanginya","menyimpulkan bahwa bantuan tidak berguna sama sekali karena perasaanmu masih berat sampai sekarang","kabari lagi konselor atau orang dewasa tepercaya bahwa kamu masih kesulitan"],answer:2,explain:"Pemulihan butuh waktu & sering perlu beberapa kali percakapan; teruslah terhubung dengan penolongmu.",hint:"Kabari lagi, jangan berhenti."},
{n:88,type:"order",micro:"Membantu teman menghubungi layanan bantuan",q:"Urutkan langkah membantu teman yang butuh bantuan di luar sekolah:",items:["Yakinkan ia bahwa mencari bantuan adalah hal yang tepat","Bersama-sama cari tahu pilihan: konselor sekolah, puskesmas, atau layanan bantuan","Libatkan orang dewasa tepercaya untuk mendampingi","Temani ia pada langkah pertama & tanyakan kabarnya setelahnya"],answer:[0,1,2,3],explain:"Yakinkan, cari pilihan, libatkan orang dewasa, lalu dampingi langkah pertamanya.",hint:"Yakinkan dulu, dampingi terakhir."},
{n:89,type:"mcq",micro:"Skenario: kamu tak punya orang dewasa di rumah untuk cerita",q:"Kamu merasa tidak bisa bercerita ke keluarga. Pilihan lain yang tepat:",options:["guru, wali kelas, konselor sekolah, kerabat lain yang tepercaya, atau layanan bantuan","tidak ada, berarti kamu harus memendamnya","hanya media sosial"],answer:0,explain:"Selalu ada lebih dari satu pintu bantuan; bila satu tertutup, coba yang lain.",hint:"Banyak pintu: guru, konselor, kerabat, layanan."},
{n:90,type:"mcq",micro:"Skenario: teman melarang keras",q:"Temanmu dalam bahaya tapi mengancam 'kalau kamu bilang, aku tidak akan menganggapmu teman lagi.' Yang benar:",options:["menunggu sampai keadaannya terlihat jelas-jelas parah baru kemudian memberi tahu orang dewasa","tetap beri tahu orang dewasa tepercaya; keselamatannya lebih penting daripada rasa marahnya sesaat","menuruti ancamannya dan diam saja supaya ia tidak marah dan tetap mau menjadi temanmu"],answer:1,explain:"Menjaga temanmu tetap hidup & aman adalah bentuk pertemanan yang paling dalam, meski ia marah untuk sementara.",hint:"Keselamatan di atas ancaman marah."},
{n:91,type:"mcq",micro:"Skenario: kamu ingin menolong tapi takut salah",q:"Kamu ingin membantu teman yang berjuang tapi takut mengatakan hal yang keliru. Yang membantu:",options:["diam saja karena takut salah bicara dan khawatir ucapanmu justru membuat keadaannya lebih buruk","memberinya banyak nasihat panjang supaya kamu terlihat sangat membantu dan benar-benar peduli kepadanya","ingat bahwa kehadiran & kesediaan mendengar sudah berarti, & orang dewasa bisa membantu bagian yang sulit"],answer:2,explain:"Kamu tidak perlu punya semua jawaban; hadir, mendengar, & menjembatani ke orang dewasa sudah sangat berarti.",hint:"Hadir & mendengar sudah berarti."},
{n:92,type:"open",micro:"Daftar penolongmu",q:"Buat daftar pribadimu: tiga orang atau tempat yang bisa kamu hubungi saat butuh bantuan, untuk jenis masalah yang berbeda.",explain:"Daftar penolong yang disiapkan sebelum krisis membuat meminta bantuan jauh lebih mudah saat dibutuhkan.",hint:"Beda jenis masalah, beda penolong.",sample:"Masalah belajar: Bu Rina (wali kelas) atau kakakku. Masalah pertemanan atau perasaan: konselor sekolah, Pak Budi. Situasi darurat atau merasa sangat tidak aman: orang tuaku, & bila perlu layanan bantuan yang bisa dibantu dihubungi orang dewasa. Aku akan menyimpan daftar ini di buku agendaku."},
{n:93,type:"mcq",micro:"Skenario: kamu lega setelah cerita",q:"Setelah akhirnya bercerita tentang masalah yang lama kamu pendam, kamu merasa lega. Pelajaran yang bisa diambil:",options:["memendam sendiri membuatnya terasa lebih berat daripada seharusnya; lain kali cerita lebih awal","seharusnya kamu tidak pernah bercerita kepada siapa pun karena sekarang semuanya jadi terbuka","kelegaan itu hanya sementara dan sebenarnya tidak berarti apa-apa bagi masalah yang kamu alami"],answer:0,explain:"Pengalaman lega sering menjadi bukti bahwa berbagi beban itu membantu.",hint:"Cerita lebih awal lain kali."},
{n:94,type:"tf",micro:"Meminta bantuan itu keterampilan seumur hidup",q:"Benar atau Salah: Kemampuan mengenali kapan butuh bantuan & memintanya dengan jelas adalah keterampilan yang berguna sepanjang hidup, bukan hanya saat sekolah.",answer:true,explain:"Orang dewasa yang sehat pun terus meminta bantuan pada keluarga, teman, & profesional saat dibutuhkan.",hint:"Berguna seumur hidup."},
{n:95,type:"mcq",micro:"Skenario: teman menolak semua bantuan",q:"Temanmu terus menolak bicara ke orang dewasa padahal ia jelas kesulitan berat. Yang bisa kamu lakukan:",options:["ikut diam dan berharap ia akan membaik sendiri tanpa melibatkan siapa pun, termasuk orang dewasa","tetap menjadi teman yang mendukung, & tetap ceritakan kekhawatiranmu ke orang dewasa tepercaya bila ada tanda bahaya","memaksanya bercerita berulang kali sampai ia marah dan akhirnya menjauh dan tidak mau bicara lagi"],answer:1,explain:"Kamu tidak bisa memaksa, tetapi kamu tetap boleh & perlu melibatkan orang dewasa bila ada tanda bahaya.",hint:"Dukung + tetap libatkan orang dewasa bila ada bahaya."},
{n:96,type:"mcq",micro:"Tanda kamu makin terampil meminta bantuan",q:"Tanda kamu makin terampil meminta bantuan:",options:["kamu makin lama memendam masalahmu sebelum akhirnya bercerita kepada orang yang kamu percayai","kamu berhenti mempercayai siapa pun dan memilih menyelesaikan semua masalahmu sendirian saja","kamu bercerita lebih awal, memilih orang yang tepat, & menyebut apa yang kamu butuhkan"],answer:2,explain:"Meminta bantuan lebih dini & lebih jelas menunjukkan keterampilan yang berkembang.",hint:"Lebih awal, orang tepat, kebutuhan jelas."},
{n:97,type:"mcq",micro:"Kebiasaan menjaga teman",q:"Manakah kumpulan kebiasaan 'menjaga teman' yang sehat?",options:["memperhatikan perubahan, mendengar tanpa menghakimi, mengajak ke orang dewasa saat serius, menjaga diri sendiri juga","berjanji merahasiakan bahaya, memikul semua masalah sendirian, dan menjauh saat merasa lelah","menyebarkan masalah teman ke banyak orang supaya semua orang ikut membantu mencari solusinya"],answer:0,explain:"Menjaga teman berarti peduli, menghubungkan ke bantuan, & tetap merawat diri sendiri.",hint:"Perhatikan, dengar, jembatani, jaga diri."},
{n:98,type:"mcq",micro:"Saat ragu di masa depan",q:"Aturan sederhana untuk 'lain kali aku ragu apakah perlu bantuan':",options:["tunggu sampai orang lain menyadari sendiri bahwa kamu sedang membutuhkan bantuan dari mereka","kalau menyangkut keselamatan atau terus mengganggu, ceritakan ke orang dewasa tepercaya","hanya minta bantuan kalau benar-benar sudah tidak ada jalan lain yang bisa kamu coba sendiri"],answer:1,explain:"Aturan yang sudah disiapkan membuat keputusan lebih mudah saat situasi membingungkan.",hint:"Keselamatan atau mengganggu = cerita."},
{n:99,type:"mcq",micro:"Mengajari orang lain",q:"Kamu bisa membantu teman lain belajar meminta bantuan dengan...",options:["mengejek mereka yang masih tidak berani meminta bantuan supaya mereka terpacu untuk berubah","menyuruh mereka menyelesaikan semua masalahnya sendirian supaya mereka belajar menjadi lebih mandiri","menceritakan bahwa kamu pernah melakukannya & itu membantu, tanpa membuka rahasia orang"],answer:2,explain:"Berbagi pengalaman bahwa meminta bantuan itu wajar & menolong bisa menular ke teman lain.",hint:"Ceritakan pengalamanmu, normalkan."},
{n:100,type:"mcq",micro:"Sintesis",q:"Inti dari 'Meminta Bantuan & Menjaga Teman' adalah...",options:["meminta bantuan adalah berani & wajar, & menjaga teman berarti mendengar, peduli, & melibatkan orang dewasa tepercaya saat masalah serius atau menyangkut keselamatan","teman sejati menyelesaikan semua masalah berdua saja tanpa melibatkan siapa pun, termasuk orang dewasa","hanya orang yang lemah yang butuh bantuan, sedangkan orang yang kuat harus menyelesaikan semuanya sendiri"],answer:0,explain:"Berani meminta bantuan untuk diri sendiri, & bagi teman: dengar, peduli, & hubungkan ke orang dewasa tepercaya, terutama saat menyangkut keselamatan.",hint:"Berani minta bantuan + jaga teman lewat orang dewasa."},
];
